import java.util.*; public class Q07_SportsLeague{static class Team{String n;int m,w,d;Team(String n,int m,int w,int d){this.n=n;this.m=m;this.w=w;this.d=d;}int points(){return w+d;}}static class Cricket extends Team{Cricket(String n,int m,int w,int d){super(n,m,w,d);}int points(){return w*2+d;}}static class Football extends Team{Football(String n,int m,int w,int d){super(n,m,w,d);}int points(){return w*3+d;}}public static void main(String[]x){Scanner s=new Scanner(System.in);while(s.hasNextLine()){String[]p=s.nextLine().split(",");Team t=p[0].equalsIgnoreCase("Cricket")?new Cricket(p[1],Integer.parseInt(p[2]),Integer.parseInt(p[3]),Integer.parseInt(p[4])):new Football(p[1],Integer.parseInt(p[2]),Integer.parseInt(p[3]),Integer.parseInt(p[4]));System.out.println("Team: "+t.n+" ("+p[0]+") Points: "+t.points());}}}
